INSERT INTO platform_rule_document (id,rule_code,rule_title,rule_version,rule_scope,content_type,content_text,content_hash,is_required,force_reaccept,rule_status,effective_at,created_at,updated_at) VALUES ('dead2e3dff7a434fa1e4aba80114fa23','factory_onboarding_fulfillment_rule','工厂入驻与履约规则','2026.09','supplier','html','<h2>工厂入驻与履约规则</h2><p>工厂需先完成资料审核并确认附加规则，才可接收工厂订单。</p><h3>一、入驻与资料</h3><ol><li>工厂应提交真实主体、联系人、经营地址和服务能力资料，并及时更新失效信息。</li><li>工厂身份与普通用户、管理员正式身份互斥，工厂只能查看和处理属于本工厂的数据。</li></ol><h3>二、接单与履约</h3><ol><li>工厂应在订单生成后两小时内接单或填写原因拒绝；超时按拒绝处理。</li><li>接单后不得普通取消；确实无法履约时须联系平台，由客服处理换货、退款或平台介入。</li><li>工厂应按订单快照准备数量、序列号、包装和运输，不得以线下约定覆盖系统订单。</li></ol><h3>三、结算</h3><ol><li>订单完成、资金结清且无争议后进入结算；平台按租金可结算收入的 20% 收取佣金。</li><li>押金赔付和核准运费不参与佣金，工厂可在结算记录中查看批次和金额来源。</li></ol>','5d059025a988cd89512af97ff2b3c1a4825b191aae45283f21373931f3890c61',1,0,'active','2026-09-02 00:00:00.000',@d2b_time,@d2b_time);
INSERT INTO platform_rule_document (id,rule_code,rule_title,rule_version,rule_scope,content_type,content_text,content_hash,is_required,force_reaccept,rule_status,effective_at,created_at,updated_at) VALUES ('68267dae17b24453a9f2812c4b9aa88b','factory_logistics_outbound_rule','工厂物流、包装与出入库规则','2026.09','supplier','html','<h2>工厂物流、包装与出入库规则</h2><p>工厂需用扫码、照片和运输凭证形成可追溯的交付证据。</p><h3>一、出库</h3><ol><li>A 类道具按序列号扫码，B 类道具按数量核验；不属于当前订单的码不得加入出库清单。</li><li>工厂应保存整体照、重点照和装车照，并按订单快照执行包装及搬运要求。</li></ol><h3>二、运输</h3><ol><li>工厂接单即接受订单中冻结的去程、回程服务与平台计价规则；接单后系统不提供运输方案拒绝或调整入口。</li><li>工厂配送或取回时，应保存实际费用和必要凭证。订单按往返合计核销，低于运费暂收池时退还用户余额，超过暂收池时不再向用户补缴。</li></ol><h3>三、归还核验</h3><ol><li>用户标记已发出后按规则进入工厂核验提醒，工厂应核对数量、外观、损坏和包装情况；无异常时不要求拍照。</li><li>发现异常应在核验期内发起索赔并上传证据；未提出问题且超过自动关闭时限的，系统可按无异常处理并释放押金。</li></ol>','c5bc639411b7cea28c7736e7f718e6077360834184813a0f7760b5ffea1bc674',1,0,'active','2026-09-02 00:00:00.000',@d2b_time,@d2b_time);
